INSERT INTO `users` (`openId`, `name`, `email`, `role`) SELECT 'team@regencivics.earth', 'ReGen Civics Team', 'team@regencivics.earth', 'admin' WHERE NOT EXISTS (SELECT 1 FROM `users` WHERE `email` = 'team@regencivics.earth');
INSERT INTO `blogEdits` (`slug`, `content`, `updatedAt`) SELECT 'heal-the-land-heal-ourselves', 'Something is wrong with how we have framed the problem.\n\nWhen we talk about ecological crisis, we talk about carbon parts per million, about species loss percentages, about ocean acidification rates. All of that is real. But it leaves something out: the human being standing in a parking lot, eating food from a plastic container, who has not put their hands in soil in years. Maybe decades. Maybe ever.\n\nWe frame land health and human health as two separate problems. They are not. They are the same problem, wearing different faces.\n\nThe Church of the Regenerative Earth was built on one core belief: we are the land. Not symbolically. We are literally made of the same stuff: the same water, the same minerals, the same microbial communities. When the land loses its living complexity, we lose ours. When the land heals, we feel it. In our bodies. In our moods. In our sense of purpose and belonging.\n\nThis is why we built Heal the Land, Heal Ourselves.\n\n## What the program actually is\n\nIt starts with food. Our bioregion here on the Big Island of Hawaii, and our partner land projects wherever they exist, offer free or heavily discounted regeneratively grown food to anyone in the community who needs it. No application. No means test. No shame. Food is a sacred good. You need it, you are welcome to it.\n\nPeople who receive food are invited to gardening days. Not required. Invited. These are not volunteer shifts. They are community days: part work, part ceremony, part shared meal, part music. People come to tend a garden and discover the garden tends them back.\n\nSome of those people feel something shift. They want to go deeper. For those who are ready, we offer land residency: extended time living alongside a land project that is being restored. The land heals through their care. They heal through the land care. These happen together, not sequentially.\n\n## Why dis-ease dissolves in soil\n\nThis is not a metaphor we are reaching for. The research is catching up to what indigenous people have known for millennia: the human microbiome is fundamentally shaped by contact with living soil ecosystems.\n\nBut beyond the biochemistry, there is something harder to measure and just as real: purpose. Meaning. The experience of mattering to something larger than yourself.\n\n## What we need from land project partners\n\nWe are looking for regenerative farms, food forests, permaculture properties, and ecological restoration sites willing to host Heal the Land days for their bioregion. In exchange, the Church builds a custom civic coordination game for your local food system at no cost. Custom quests, token rewards, governance tools, community onboarding.\n\nYou bring the land. We bring the game. Together we build something better.\n\nApply at [regencivics.earth/land](/land#heal-program) and tell us about your land, your vision, and what healing you are working toward.\n\nThe land is waiting. The people are waiting. We just need somewhere to meet.\n\n*Church of the Regenerative Earth  |  regencivics.earth*', NOW() WHERE NOT EXISTS (SELECT 1 FROM `blogEdits` WHERE `slug` = 'heal-the-land-heal-ourselves');
INSERT INTO `forumPosts` (`categoryId`, `authorId`, `title`, `content`, `isPinned`) SELECT (SELECT `id` FROM `forumCategories` WHERE `slug` IN ('land-projects','active-projects') ORDER BY FIELD(`slug`,'land-projects','active-projects') LIMIT 1), (SELECT `id` FROM `users` WHERE `email` = 'team@regencivics.earth'), 'Heal the Land, Heal Ourselves: We are Looking for Land Project Partners', 'The Church of the Regenerative Earth has designed a three-stage community healing ministry called **Heal the Land, Heal Ourselves**.\n\nIt starts with free food outreach. Grows into community gardening days on partner land project sites. And for those called to go deeper, offers land residency alongside projects being restored.\n\n**We need land project partners.**\n\nIf you are stewarding a regenerative farm, food forest, permaculture property, or ecological restoration site, we want to talk. In exchange for hosting the program, the Church designs and builds a custom civic coordination game for your local food system at no cost. Custom quests, token rewards, governance tools, community onboarding.\n\nYou bring the land. We bring the game. Together we build something better.\n\n**Learn more:** [regencivics.earth/heal-the-land](/heal-the-land)\n**Apply:** [regencivics.earth/land](/land#heal-program)\n\nThe land is waiting. The people are waiting. We just need somewhere to meet.', 1 WHERE NOT EXISTS (SELECT 1 FROM `forumPosts` WHERE `title` = 'Heal the Land, Heal Ourselves: We are Looking for Land Project Partners');
